import java.util.Scanner;

public class Main {
    public static long power_mod(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        final long pcon = 1000000007;
        long[] inv_table = new long[1000003];
        inv_table[1] = 1;
        for (long i = 2; i < 1000003; ++i) {
            long a = pcon / i;
            long b = pcon % i;
            long c = (a * (pcon - inv_table[(int)b])) % pcon;
            inv_table[(int)i] = c;
        }
        long total_ans = 0;
        if (k == 0) {
            total_ans = 1;
            for (long i = 0; i < p - 1; ++i) {
                total_ans = (total_ans * p) % pcon;
            }
        } else {
            long prod = 1;
            int first_found_flag = 0;
            long idx_jj = 0;
            for (long i = 1; i < p; ++i) {
                prod = (prod * k) % p;
                if ((prod % p) == 1 && first_found_flag == 0) {
                    idx_jj = i;
                    first_found_flag = 1;
                }
            }
            total_ans = 1;
            long t = (p - 1) / idx_jj;
            if (k == 1) {
                total_ans = 1;
                for (long i = 0; i < p; ++i) {
                    total_ans = (total_ans * p) % pcon;
                }
            } else {
                long sum_res = 0;
                for (long i = 1; i <= t; ++i) {
                    long temp = (inv_table[(int)i] * (t - i + 1)) % pcon;
                    temp = (temp * t) % pcon;
                    temp = (temp * idx_jj) % pcon;
                    sum_res = (sum_res + temp) % pcon;
                }
                total_ans = (total_ans + sum_res) % pcon;
            }
        }
        System.out.println(total_ans);
        sc.close();
    }
}
